mapper.select:
select
a.device_id,
a.device_model,
a.pms_type,
a.pms_id,
a.device_vendor,
a.production_date,
a.used_time,
a.disable_date,
a.last_maintenance,
a.maintenance_count,
a.organization,
a.department,
a.responsible_person,
a.latitude,
a.longitude,
a.ip,
a.port,
a.voltage_level,
a.sequence_point,
a.real_code,
a.address
from t_std_device_attr a
where 1 = 1
 and a.device_id = #{deviceId, jdbcType=BIGINT}
 and a.device_model = #{deviceModel, jdbcType=INTEGER}
 and a.pms_type = #{pmsType, jdbcType=VARCHAR}
 and a.pms_id = #{pmsId, jdbcType=VARCHAR}
 and a.device_vendor = #{deviceVendor, jdbcType=VARCHAR}
 and a.production_date = #{productionDate, jdbcType=TIMESTAMP}
 and a.used_time = #{usedTime, jdbcType=TIMESTAMP}
 and a.disable_date = #{disableDate, jdbcType=TIMESTAMP}
 and a.last_maintenance = #{lastMaintenance, jdbcType=TIMESTAMP}
 and a.maintenance_count = #{maintenanceCount, jdbcType=VARCHAR}
 and a.organization = #{organization, jdbcType=VARCHAR}
 and a.department = #{department, jdbcType=VARCHAR}
 and a.responsible_person = #{responsiblePerson, jdbcType=VARCHAR}
 and a.latitude = #{latitude, jdbcType=VARCHAR}
 and a.longitude = #{longitude, jdbcType=VARCHAR}
 and a.ip = #{ip, jdbcType=VARCHAR}
 and a.port = #{port, jdbcType=INTEGER}
 and a.voltage_level = #{voltageLevel, jdbcType=VARCHAR}
 and a.sequence_point = #{sequencePoint, jdbcType=VARCHAR}
 and a.real_code = #{realCode, jdbcType=VARCHAR}
 and a.address = #{address, jdbcType=VARCHAR}

